import {
  AutoStories,
  Bookmarks,
  Category,
  Grade,
  History,
  MenuBook,
  Person,
  ShowChart,
  Stars,
  TaskAlt,
  Whatshot,
} from "@mui/icons-material";
import { Stack } from "@mui/material";
import type { ReactNode } from "react";
import {
  StatCard,
  StatList,
  StatSummary,
  TotalsBand,
  VitalsCard,
  YearVitalsPair,
  type StatListBaseProps,
} from "../common/Stats";
import { TopCategoryBand } from "../common/TopList";
import { GroupedStatList } from "../common/GroupedStatList";
import { Hero } from "../common/Hero";
import { Section, StatBand } from "../common/SectionRail";
import { CURRENT_PLAINDATE, formatDate, type YearNumber } from "../common/date";
import type { YearType } from "../common/filterReducer";
import { useSelectBox } from "../common/SelectBoxHook";
import { stated } from "../common/population";
import { genreToColour, scoreBand, scoreBandToColour, scoreBands } from "../utils/types";
import { bookSubtitle } from "./cardData";
import { bookScoreChip, bookStatListSharedProps, bySeriesThenRelease } from "./drilldown";
import BookCardMediaImage, { BookFranchiseStrip } from "./CardMediaImage";
import { BOOK_SECTIONS } from "./sections";
import { FORMATS, formatToColour, groupToColour, type Book, type Measure } from "./types";
import {
  bookHeroStats,
  bookKey,
  bookTopOptions,
  bookTotals,
  booksInYear,
  groupBooksBy,
  measureOf,
  perBookAverages,
  statsCardLabelFinished,
  statsCardLabelPages,
  yearlyAverages,
  type BookTopOption,
} from "./statsData";
import "../utils/arrayUtils";
import { useScheme } from "../common/useScheme";
import { captionLines, type DrilldownGroup } from "../common/statsData";
import { categoryKeys } from "../common/filterSchema";
import { bookFilters } from "./filters";

const Stats = ({
  data,
  upTo,
  reading,
  measure,
  yearType,
  yearTo,
}: {
  data: Book[];
  /** The rows up to the scope's year whatever its reading, for the cards titled that way. */
  upTo: Book[];
  /** Every book in progress, most recently started first. Computed by `Graphs`, which also
      decides on it whether the rail offers a chip pointing at the hero below. */
  reading: Book[];
  measure: Measure;
  yearType: YearType;
  yearTo: YearNumber;
}) => {
  return (
    <Stack spacing={2}>
      {/* No book in hand and there is no "now" to lead with. */}
      {reading.length > 0 && (
        <Section id={BOOK_SECTIONS.now}>
          <BookHero book={reading[0]} />
        </Section>
      )}
      <Section id={BOOK_SECTIONS.vitals}>
        <StatBand>
          {/* The first card and the average beside it count `upTo` rather than `data`: the scope
              read as a ceiling, which is what a card titled "All time" or "Up to 2019" states
              under either reading — fed the "In 2026" rows, it would restate the in-year figures
              under the wrong words. The in-year card narrows `data`, which under that reading is
              already the year. */}
          <YearVitalsPair
            yearTo={yearTo}
            yearType={yearType}
            allTime={bookTotals(upTo)}
            inYear={booksInYear(data, yearTo)}
          />
          <StatSummary
            icon={<ShowChart />}
            title="Yearly Average"
            stats={yearlyAverages(upTo)}
          />
          <BookAverage data={data} />
          <Vitals
            data={data}
            measure={measure}
            genreGroups={groupBooksBy(data, "genre", measure)}
          />
        </StatBand>
      </Section>
      <Section id={BOOK_SECTIONS.top}>
        <StatBand>
          <TopCategories
            data={data}
            measure={measure}
          />
        </StatBand>
      </Section>
      <Section id={BOOK_SECTIONS.explore}>
        <StatBand>
          <RecentlyFinished data={data} />
          <MostRead
            data={data}
            measure={measure}
          />
        </StatBand>
      </Section>
    </Stack>
  );
};

/**
 * The book in hand, promoted. Its figures are its own — hours so far, days in, pages, its place in
 * its series — and the library's totals stay in the cards below, which are their single home.
 */
const BookHero = ({ book }: { book: Book }) => {
  const scheme = useScheme();

  return (
    <Hero
      item={book}
      MediaComponent={BookCardMediaImage}
      shape="cover"
      kicker={`Reading since ${formatDate(book.startDate)}`}
      title={book.name}
      subtitle={bookSubtitle(book, scheme)}
      stats={bookHeroStats(book, CURRENT_PLAINDATE, "hero")}
      strip={
        <BookFranchiseStrip
          book={book}
          variant="hero"
        />
      }
    />
  );
};

/**
 * Genre, score and format, as one band each. Genre first because it is the vocabulary every row
 * answers — a score is optional and a library read on one device is one format — and its segments
 * run biggest first, since the vocabulary is open-ended and has no order of its own.
 */
const Vitals = ({
  data,
  measure,
  genreGroups,
}: {
  data: Book[];
  measure: Measure;
  /** The genre grouping under the current measure, which orders the band's segments. */
  genreGroups: DrilldownGroup<Book>[];
}) => {
  const scheme = useScheme();

  const measureFunc = (books: Book[]) => measureOf(books, measure);

  return (
    <VitalsCard>
      <TotalsBand
        title="Genre"
        icon={<Category />}
        data={data}
        measureFunc={measureFunc}
        group={genreGroups.map((group) => group.name)}
        groupOf={(book) => book.genre}
        groupToColour={(ele) => genreToColour(ele, scheme)}
        measureLabel={measure}
      />
      <TotalsBand
        title="Score"
        icon={<Grade />}
        data={data}
        measureFunc={measureFunc}
        group={[...scoreBands]}
        groupOf={(book) => scoreBand(book.score)}
        groupToColour={(ele) => scoreBandToColour(ele, scheme)}
        measureLabel={measure}
      />
      <TotalsBand
        title="Format"
        icon={<MenuBook />}
        data={data}
        measureFunc={measureFunc}
        group={[...FORMATS]}
        groupOf={(book) => book.format}
        groupToColour={(ele) => formatToColour(ele, scheme)}
        measureLabel={measure}
      />
    </VitalsCard>
  );
};

const BookAverage = ({ data }: { data: Book[] }) => {
  const { pages, hours, days } = perBookAverages(data);
  return (
    <StatCard
      icon={<AutoStories />}
      title="Per Book"
      content={[
        ["Pages", pages],
        ["Hours", hours],
        ["Days", days],
      ]}
    />
  );
};

const TopCategories = ({ data, measure }: { data: Book[]; measure: Measure }) => {
  const scheme = useScheme();

  return (
    <TopCategoryBand
      defaults={["genre", "author", "franchise"]}
      options={bookTopOptions}
      icons={optionIcons}
      groups={(option) => groupBooksBy(data, option, measure)}
      colourOf={(option, top: Book) => groupToColour(option, top, scheme)}
      measureLabel={measure}
      categories={categoryKeys(bookFilters, { series: "bookSeries" })}
    />
  );
};

const optionIcons: Record<BookTopOption, ReactNode> = {
  genre: <Category />,
  author: <Person />,
  franchise: <Stars />,
  series: <Bookmarks />,
  format: <MenuBook />,
  score: <Grade />,
  status: <TaskAlt />,
  decade: <History />,
};

/**
 * Only what has closed, newest first: the book in hand is the hero's, and a strip titled
 * "finished" listing it says something false. The filter also leaves every entry a date to sort
 * by, where `sortByKey` would otherwise head the list with the undated one.
 */
const RecentlyFinished = ({ data }: { data: Book[] }) => (
  <BookStatList
    icon={<History />}
    title="Recently Finished"
    content={data.filter((book) => book.endDate).sortByKey("endDate")}
    labelComponent={statsCardLabelFinished}
  />
);

const bookMostReadOptions = ["name", ...bookTopOptions] as const;

const MostRead = ({ data, measure }: { data: Book[]; measure: Measure }) => {
  // Opens on single books, the one ranking nothing else on the page draws: the Top band beside it
  // already ranks authors, genres and franchises, and opened on any of those the two sections
  // state the same five names at the same counts.
  const [option, controls] = useSelectBox(bookMostReadOptions, "name", "By");

  if (option === "name") {
    return (
      <MostReadBooks
        data={data}
        controls={controls}
      />
    );
  }
  return (
    <MostReadCategory
      data={data}
      measure={measure}
      controls={controls}
      category={option}
    />
  );
};

const MostReadBooks = ({ data, controls }: { data: Book[]; controls: ReactNode }) => {
  const most = data.filter((book) => book.hours).sortByKey("hours");
  return (
    <BookStatList
      controls={controls}
      icon={<Whatshot />}
      title="Most Read"
      content={most}
      labelComponent={statsCardLabelPages}
    />
  );
};

const MostReadCategory = ({
  data,
  measure,
  category,
  controls,
}: {
  data: Book[];
  measure: Measure;
  category: BookTopOption;
  controls: ReactNode;
}) => {
  const scheme = useScheme();

  return (
    <GroupedStatList
      icon={<Whatshot />}
      controls={controls}
      title="Most Read"
      option={category}
      groups={groupBooksBy(data, category, measure)}
      // Name over figure, a cell a row, as every other list on this tab writes its cards: this band
      // stands Recently Finished's date over its pages beside it, and two footers of two lines end
      // at one height at every width, where a row of two cells wraps at a width its own words set
      // and leaves one card a line taller than its neighbour across the band. A strip's caption
      // drops the name and keeps the figure (`groupCaption`), which is what the shelf is ranked by.
      labelComponent={(group) => [[group.name], [stated(group.count, measure)]]}
      colourOf={(top) => groupToColour(category, top, scheme)}
      MediaComponent={BookCardMediaImage}
      // Series order where the sheet numbers one, reading order where it does not: a drill-down
      // into a series is read the way the series is.
      dialogSort={(books) => books.toSorted(bySeriesThenRelease)}
      nameOf={bookKey}
      dialogLabelComponent={statsCardLabelFinished}
      dialogChipComponent={(book) => bookScoreChip(book, scheme)}
      {...bookStatListSharedProps}
    />
  );
};

const BookStatList = (
  props: Omit<
    StatListBaseProps<Book>,
    "MediaComponent" | "chipComponent" | "nameComponent" | keyof typeof bookStatListSharedProps
  >,
) => {
  const scheme = useScheme();

  return (
    <StatList
      chipComponent={(book) => bookScoreChip(book, scheme)}
      MediaComponent={BookCardMediaImage}
      nameComponent={bookKey}
      // This tab writes a cell a row, and a strip's own caption reads the first row alone, which
      // would state a date without its pages, or pages without the hours the list is ranked by.
      captionOf={(book) => captionLines(props.labelComponent(book).flat())}
      {...bookStatListSharedProps}
      {...props}
    />
  );
};

export default Stats;
